        // the bumblebee queen pins read 8+6 (the capture hyphen settled as
        // the plus)
    if (mm2bcBeeQueenHdNum() != 8
            || mm2bcBeeQueenHdBonus() != 6
        )
            ++bad;
        printf("R798 MM2 letters BC audit: bad %d\n", bad);
        if (bad) return 1;
