    // ---- R813: the MM2 letter S live def walk ----
    // The 33 promoted letter S defs
    // cross-checked live against the mm2s pins:
    // every stat cell of the 33-row SStats grid,
    // the mm2_print xp source and the xpValue
    // formula, the per-def prose markers, and the
    // registry census floor 733 -> at least 766.
    {
        using namespace rules;
        int bad = 0;
        static const char* kS[33] = {
            "sandling",
            "scorpion_large",
            "scorpion_huge",
            "scum_creeper",
            "selkie",
            "shade",
            "sirine",
            "skeleton_animal",
            "skunk",
            "slime_creature",
            "slime_olive",
            "snake_constrictor",
            "snake_poisonous",
            "solar",
            "solifugid_large",
            "solifugid_huge",
            "solifugid_giant",
            "spectator",
            "spider_giant_marine",
            "spriggan",
            "squealer",
            "squirrel_giant_black",
            "squirrel_ordinary",
            "squirrel_carnivorous_flying",
            "stegocentipede",
            "stench_kow",
            "stone_guardian",
            "storoper",
            "sundew_giant",
            "swan",
            "swanmay",
            "swordfish",
            "taer",
        };
        static const char* kSMark[33] = {
            "moving, sliding sand",
            "weaker than normal",
            "instantly killed",
            "shearing plates of hornlike substance",
            "becomes a sort of sealwere",
            "essence of shadowstuff",
            "save vs. poison or become an idiot",
            "1-1/2 per experience level",
            "cloud of stinking musk",
            "metamorphosed hosts of olive slime",
            "akin to green slime",
            "bite and coiling to constrict",
            "Use the table below to determine strength",
            "arrows of slaying",
            "sucker-like clamps",
            "nocturnal variety",
            "warm desert climates",
            "guard for up to 101 years",
            "huge air-filled underwater nests",
            "cousins of the gnomes",
            "grasp the limb it is upon",
            "small, shiny objects",
            "bite only in self defense",
            "range is 5 feet for every foot",
            "insane genetic manipulator",
            "cattle of the Nine Hells",
            "golem-like figure",
            "stone roper",
            "hundreds of tendrils",
            "blind and disorient",
            "feather token",
            "fearsome weapon",
            "polished teeth",
        };
        for (int i = 0; i < 33; ++i) {
            const auto* d = reg.find(kS[i]);
            if (!d) { ++bad; continue; }
            if (d->xpSource != "mm2_print")
                ++bad;
            if (d->xpValue != d->xpBase
                + d->avgHp * d->xpPerHp)
                ++bad;
            if (d->armorClass != mm2sSStatAc(i))
                ++bad;
            if (d->hitDiceNum != mm2sSStatHd(i))
                ++bad;
            if (d->hitDiceBonus
                != mm2sSStatHdBonus(i))
                ++bad;
            if (d->avgHp != mm2sSStatAvgHp(i))
                ++bad;
            if (d->attacks != mm2sSStatAttacks(i))
                ++bad;
            if (d->xpBase != mm2sSStatXp(i))
                ++bad;
            if (d->xpPerHp != mm2sSStatXpHp(i))
                ++bad;
            if (d->lairPct != mm2sSStatLairPct(i))
                ++bad;
            if (d->moveRate != mm2sSStatMove(i))
                ++bad;
            if (d->magicResist != mm2sSStatMr(i))
                ++bad;
            if (d->text.find(kSMark[i])
                == std::string::npos)
                ++bad;
        }
        if ((int)reg.all().size()
            < mm2sRegistryAfter())
            ++bad;
        printf("R813 MM2 letter S live defs: bad %d\n",
               bad);
        if (bad) return 1;
    }
    // ---- R814 MM2 letters TUV walk audit ----
    // THE MM2 LETTERS TUV WALK - the tarrasque p. 117 (its treasure and lair
    // cells the See-below read), the tasloi p. 118, the giant harvester
    // termite variant table pp. 118-119 (the worker and soldier columns, plus
    // the king and queen the royal-pair inline stats), the thessalhydra, the
    // thri-kreen, the thunder beast and the time elemental p. 119, the
    // thunderherder p. 120, the transposer p. 120, the tri-flower frond p.
    // 121, the troll marine (scrag) variant table p. 121 (the fresh and salt
    // water columns), the twilight bloom and the land urchin p. 122, the
    // ustilagor p. 122 and the vagabond pp. 122-123, the vargouille p. 123,
    // the vegepygmy, the verme and the vilstrak p. 124, the vulchling and the
    // vulture variant table p. 125 (the giant and ordinary columns); the
    // TUV-FLIP round: the Letter T, U and V gap boxes flip to closed (27
    // closed, 10 open). TWENTY-SIX .lua defs ride the R791 data_files
    // extension, registry 766 -> 792; TWENTY-ONE entry heads carrying
    // TWENTY-TWO stat blocks (the termite royal pair the one extra block), no
    // prior-owned heads, no doctrine-only heads. THE SETTLED READS (capture
    // primary, the 1eonline transcription the cross-check voice): the
    // tarrasque 300 hp the flat-hp path (hdNum 0) and its AC -3 the UNQUOTED
    // number (the phoenix precedent); the transposer xp VI/625 the
    // capture-wins read (the transcription 525); the scrag saltwater 6+12 the
    // capture-wins read (the transcription 5+12); the thessalhydra IX/5800
    // (the capture 5S00, the S an 8 artifact, the transcription the confirm);
    // the ordinary vulture AC 6 the capture-wins read (the transcription 7)
    // and the two vulture xp rows pinned verbatim (the giant I/20 + 2/hp, the
