        for (int L = 0; L < 10; ++L) {
            int party = 0;
            for (int r = 0; r < 19; ++r) {
                if (encDie(L, r) != r + 2)
                    ++bad;
                if (encSpecial(L, r) == 1) {
                    ++party;
                    if (encDie(L, r) != encPartyDie(L))
                        ++bad;
                    if (encSrc(L, r) != 0
                        || encNumMin(L, r) != 0
                        || encNumMax(L, r) != 0)
                        ++bad;
                }
                if (encSpecial(L, r) == 2) {
                    if (L != 9) ++bad;
                    if (encNumMin(L, r) != 0
                        || encNumMax(L, r) != 0)
                        ++bad;
                }
                if (encSpecial(L, r) == 0) {
                    if (encNumMin(L, r) < 1)
                        ++bad;
                    if (encNumMax(L, r)
                        < encNumMin(L, r))
                        ++bad;
                    if (encSrc(L, r) == 0)
                        ++bad;
                }
                const char* k = kEncD[L][r];
                if (k[0] != 0) {
                    const auto* d = reg.find(k);
                    if (!d) ++bad;
                }
            }
            if (party != 1) ++bad;
        }
        if (!reg.find("fire_giant")) ++bad;
